python3 -c "
import csv, json, collections, difflib, unicodedata, re
labels={l['customer_id']:l for l in csv.DictReader(open('dev/labels_dev.csv'))}
cust={c['customer_id']:c for c in csv.DictReader(open('dev/customers_dev.csv'))}
wl=json.load(open('watchlist.json'))
def norm(s):
    s=unicodedata.normalize('NFD',s); s=''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z ]',' ',s.lower())
names=[]
for e in wl:
    for n in [e['primary_name']]+[a['name'] for a in e['aliases']]:
        names.append((norm(n),e,n))
byclass=collections.defaultdict(list)
for cid,l in labels.items(): byclass[l['class']].append(cid)
for cls in ['D1_name_dob_conflict','D2_near_name','D5_partial_dob_conflict','D6_same_given','D3_weak_alias_alone']:
    print('=====',cls)
    for cid in byclass[cls][:25]:
        c=cust[cid]; cn=norm(c['full_name'])
        best=sorted(names,key=lambda t:-difflib.SequenceMatcher(None,cn,t[0]).ratio())[:2]
        s=' ;; '.join(f\"{b[2]!r}[{b[1]['uid']}] dob={b[1]['dob']}\" for b in best)
        print(f\"{c['full_name']!r} dob={c['dob']} id={c['id_type']}:{c['id_number']} >> {s}\")
" 2>&1 | head -160

