#!/usr/bin/env python3
"""Score decisions against dev labels, per class."""
import csv, sys, collections, json

dec = {r['customer_id']: r for r in csv.DictReader(open(sys.argv[1]))}
lab = {r['customer_id']: r for r in csv.DictReader(open(sys.argv[2]))}
cust = {r['customer_id']: r for r in csv.DictReader(open(sys.argv[3]))} if len(sys.argv) > 3 else {}
wl = {e['uid']: e for e in json.load(open('/app/watchlist.json'))}

tp = fp = fn = 0
uid_ok = 0
per = collections.defaultdict(lambda: [0, 0])   # class -> [hit, total]
errs = collections.defaultdict(list)
for cid, l in lab.items():
    d = dec.get(cid, {'decision': 'NO_MATCH', 'matched_uid': ''})
    exp = l['expected_decision']
    cls = l['class']
    if exp == 'MATCH':
        per[cls][1] += 1
        if d['decision'] == 'MATCH':
            tp += 1
            if d['matched_uid'] == l['expected_uid']:
                uid_ok += 1
                per[cls][0] += 1
            else:
                errs['WRONGUID:' + cls].append((cid, d['matched_uid'], l['expected_uid']))
        else:
            fn += 1
            errs['MISS:' + cls].append((cid, '', l['expected_uid']))
    else:
        per[cls][1] += 1
        if d['decision'] == 'MATCH':
            fp += 1
            errs['FP:' + cls].append((cid, d['matched_uid'], ''))
        else:
            per[cls][0] += 1

rec = tp / (tp + fn) if tp + fn else 1
prec = tp / (tp + fp) if tp + fp else 1
print(f'TP={tp} FP={fp} FN={fn} recall={rec:.4f} precision={prec:.4f} uid_ok={uid_ok}/{tp}={uid_ok/max(tp,1):.4f}')
for cls in sorted(per):
    h, t = per[cls]
    flag = ''
    if cls.startswith('T') and t and h / t < 0.90:
        flag = '  <-- LOW'
    if cls.startswith(('D', 'R')) and t and (t - h) / t > (0.01 if cls.startswith('R') else 0.05):
        flag = '  <-- HIGH FP'
    print(f'{cls:28s} {h:4d}/{t:4d} = {h/t:.3f}{flag}')

if len(sys.argv) > 4:
    print('\n--- errors ---')
    for k in sorted(errs):
        print('==', k, len(errs[k]))
        for cid, got, exp in errs[k][:40]:
            c = cust.get(cid, {})
            g = wl.get(got)
            e = wl.get(exp)
            def show(x):
                if not x: return 'None'
                al = '|'.join(a['name'] + '(' + a['strength'][0] + ')' for a in x['aliases'])
                return f"{x['uid']} {x['primary_name']!r} sc={x['script_name']} dob={x['dob']} al={al}"
            print(f"  {cid} {c.get('full_name')!r} dob={c.get('dob')} id={c.get('id_type')}:{c.get('id_number')} t={c.get('type')}")
            if got: print(f"      GOT {show(g)}")
            if exp: print(f"      EXP {show(e)}")

