#!/usr/bin/env python3
"""List NO_MATCH customers that are 'nearly' a match, for manual review."""
import sys, json, csv, re, difflib, collections
sys.path.insert(0, '/app')
import screen as S

raw = json.load(open('/app/watchlist.json'))
lex = S.ScriptLex(); lex.learn(raw)
entries = S.build_entries(raw, lex)
by = {e.uid: e for e in entries}

cust_file = sys.argv[1] if len(sys.argv) > 1 else '/app/customers.csv'
dec_file = sys.argv[2] if len(sys.argv) > 2 else '/app/decisions.csv'
customers = list(csv.DictReader(open(cust_file)))
dec = {r['customer_id']: r for r in csv.DictReader(open(dec_file))}


def skel(tok):
    """very loose consonant skeleton for blocking"""
    t = S.fold(tok)
    t = re.sub(r'[^a-z]', '', t)
    t = re.sub(r'(sch|sh|ch|tsch|sz|cz|zh|kh|gh|tch)', 'C', t)
    out = []
    for ch in t:
        if ch in 'aeiouyhw':
            continue
        if ch in 'szxc':
            ch = 's'
        if ch in 'kgq':
            ch = 'k'
        if ch in 'jgd':
            ch = 'd'
        if ch in 'bpv f':
            ch = 'b'
        if out and out[-1] == ch:
            continue
        out.append(ch)
    return ''.join(out)


# index entries by loose skeleton of each core token
idx = collections.defaultdict(set)
names = {}
for e in entries:
    for f in e.forms:
        if f.toks is not None:
            toks = [t.raw for t in f.toks if t.kind in ('core', 'nasab')]
        else:
            toks = f.words
        names.setdefault(e.uid, []).append(' '.join(toks))
        for t in toks:
            idx[skel(t)].add(e.uid)

n = 0
for c in customers:
    cid = c['customer_id']
    if dec[cid]['decision'] == 'MATCH':
        continue
    name = c['full_name']
    if S.is_script(name):
        name = lex.latin(name)
    typ = (c['type'] or 'individual').lower()
    toks = [t for t in S.split_tokens(name)]
    hit = collections.Counter()
    for t in toks:
        for u in idx.get(skel(t), ()):
            hit[u] += 1
    best = [(u, k) for u, k in hit.items() if k >= 2 and by[u].type == typ]
    if not best:
        continue
    for u, k in best[:3]:
        e = by[u]
        cd = S.parse_dob(c['dob'])
        ok, _ = S.dob_compatible(cd, e.dob)
        if not ok:
            continue
        n += 1
        print(f"{cid} {c['full_name']!r} dob={c['dob']} t={typ} || {u} {names[u]} dob={e.dob}")
        break
print('near misses:', n)

