            for t in ftoks:
                for k in t.keys:
                    idx[k].add(ent.uid)
    return idx


def id_index(entries):
    idx = defaultdict(set)
    for ent in entries:
        for t, num in ent.ids:
            idx[(t, num)].add(ent.uid)
            idx[(None, num)].add(ent.uid)
    return idx


TYPE_ALIASES = {
    "individual": "individual", "person": "individual", "natural person":
    "individual", "individuals": "individual", "ind": "individual",
